16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	import org.springframework.samples.petclinic.rest.validation.CustomerCodeGenerator;
20	import org.springframework.samples.petclinic.rest.validation.LuhnCheckDigit;
21	import org.springframework.samples.petclinic.rest.validation.TelephoneFormatter;
22	
23	import jakarta.persistence.*;
24	import jakarta.validation.constraints.NotEmpty;
25	import jakarta.validation.constraints.Pattern;
26	
27	import java.time.LocalDate;
28	import java.util.*;
29	
30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "title")
42	    private String title;
43	
44	    @Column(name = "address")
45	    @NotEmpty
46	    private String address;
47	
48	    @Column(name = "address_line1")
49	    private String addressLine1;
50	
51	    @Column(name = "address_line2")
52	    private String addressLine2;
53	
54	    @Column(name = "city")
55	    @NotEmpty
56	    private String city;
57	
58	    @Column(name = "telephone")
59	    @NotEmpty
60	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form: '+' followed by 8 to 15 digits")
61	    private String telephone;
62	
63	    @Column(name = "email")
64	    private String email;
65	
66	    @Column(name = "postcode")
67	    private String postcode;
68	
69	    @Column(name = "registration_date")
70	    private LocalDate registrationDate;
71	
72	    @Column(name = "birth_date")
73	    private LocalDate birthDate;
74	
75	    @Column(name = "customer_code")
76	    private String customerCode;
77	
78	    @Column(name = "household_id")
79	    private String householdId;
80	
81	    @Column(name = "namesake_count")
82	    private Integer namesakeCount;
83	
84	    @Column(name = "household_size")
85	    private Integer householdSize;
86	
87	    @Column(name = "membership_number")
88	    private String membershipNumber;
89	
90	    @Column(name = "possible_duplicate_of")
91	    private Integer possibleDuplicateOf;
92	
93	    @Column(name = "deleted", nullable = false)
94	    private boolean deleted;
95	
96	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
97	    private Set<Pet> pets;
98	
99	    /**
100	     * Default the registration date to the server's current date when none was
101	     * supplied, then roll the effective date forward onto a business day so a
102	     * weekend registration date always lands on the following Monday. Runs only
103	     * on insert.
104	     */
105	    @PrePersist
106	    private void defaultRegistrationDate() {
107	        LocalDate effectiveDate = this.registrationDate == null ? LocalDate.now() : this.registrationDate;
108	        this.registrationDate = BusinessDayAdjuster.toBusinessDay(effectiveDate);
109	    }
110	
111	    public String getTitle() {
112	        return this.title;
113	    }
114	
115	    public void setTitle(String title) {
116	        this.title = title;
117	    }
118	
119	    public String getAddress() {
120	        return this.address;
121	    }
122	
123	    public void setAddress(String address) {
124	        this.address = address;
125	    }
126	
127	    public String getAddressLine1() {
128	        return this.addressLine1;
129	    }
130	
131	    public void setAddressLine1(String addressLine1) {
132	        this.addressLine1 = addressLine1;
133	    }
134	
135	    public String getAddressLine2() {
136	        return this.addressLine2;
137	    }
138	
139	    public void setAddressLine2(String addressLine2) {
140	        this.addressLine2 = addressLine2;
141	    }
142	
143	    public String getCity() {
144	        return this.city;
145	    }
146	
147	    public void setCity(String city) {
148	        this.city = city;
149	    }
150	
151	    public String getTelephone() {
152	        return this.telephone;
153	    }
154	
155	    public void setTelephone(String telephone) {
156	        this.telephone = telephone;
157	    }
158	
159	    public String getEmail() {
160	        return this.email;
161	    }
162	
163	    public void setEmail(String email) {
164	        this.email = email;
165	    }
166	
167	    public String getPostcode() {
168	        return this.postcode;
169	    }
170	
171	    public void setPostcode(String postcode) {
172	        this.postcode = postcode;
173	    }
174	
175	    public LocalDate getRegistrationDate() {
176	        return this.registrationDate;
177	    }
178	
179	    public void setRegistrationDate(LocalDate registrationDate) {
180	        this.registrationDate = registrationDate;
181	    }
182	
183	    public LocalDate getBirthDate() {
184	        return this.birthDate;
185	    }
186	
187	    public void setBirthDate(LocalDate birthDate) {
188	        this.birthDate = birthDate;
189	    }
190	
191	    public String getCustomerCode() {
192	        return this.customerCode;
193	    }
194	
195	    public void setCustomerCode(String customerCode) {
196	        this.customerCode = customerCode;
197	    }
198	
199	    public String getHouseholdId() {
200	        return this.householdId;
201	    }
202	
203	    public void setHouseholdId(String householdId) {
204	        this.householdId = householdId;
205	    }
206	
207	    public Integer getNamesakeCount() {
208	        return this.namesakeCount;
209	    }
210	
211	    public void setNamesakeCount(Integer namesakeCount) {
212	        this.namesakeCount = namesakeCount;
213	    }
214	
215	    public Integer getHouseholdSize() {
216	        return this.householdSize;
217	    }
218	
219	    public void setHouseholdSize(Integer householdSize) {
220	        this.householdSize = householdSize;
221	    }
222	
223	    public String getMembershipNumber() {
224	        return this.membershipNumber;
225	    }
226	
227	    public void setMembershipNumber(String membershipNumber) {
228	        this.membershipNumber = membershipNumber;
229	    }
230	
231	    public Integer getPossibleDuplicateOf() {
232	        return this.possibleDuplicateOf;
233	    }
234	
235	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
236	        this.possibleDuplicateOf = possibleDuplicateOf;
237	    }
238	
239	    /**
240	     * Return whether this owner has been soft-deleted. A newly created owner is not deleted; a
241	     * {@code DELETE /api/owners/{id}} flags the owner deleted while retaining its record.
242	     */
243	    public boolean isDeleted() {
244	        return this.deleted;
245	    }
246	
247	    public void setDeleted(boolean deleted) {
248	        this.deleted = deleted;
249	    }
250	
251	    /**
252	     * Return this owner's self link: the canonical API path of this owner, {@code /api/owners/}
253	     * followed by its {@link #getId() id}.
254	     */
255	    @Transient
256	    public String getSelfLink() {
257	        return "/api/owners/" + this.getId();
258	    }
259	
260	    /**
261	     * Return whether this owner is a possible duplicate: true when it was created while an existing
262	     * owner already shared its last name and postcode under a different telephone, i.e. when a
263	     * {@link #getPossibleDuplicateOf() possible-duplicate-of} owner id is present.
264	     */
265	    @Transient
266	    public boolean getPossibleDuplicate() {
267	        return this.possibleDuplicateOf != null;
268	    }
269	
270	    /**
271	     * Return this owner's name formatted as {@code LastName, FirstName}.
272	     */
273	    @Transient
274	    public String getDisplayName() {
275	        return this.getLastName() + ", " + this.getFirstName();
276	    }
277	
278	    /**
279	     * Return this owner's salutation: the {@link #getTitle() title} followed by a space and the
280	     * last name (e.g. {@code DR Franklin}), or just the last name when no title was supplied.
281	     */
282	    @Transient
283	    public String getSalutation() {
284	        if (this.title == null || this.title.isBlank()) {
285	            return this.getLastName();
286	        }
287	        return this.title + " " + this.getLastName();
288	    }
289	
290	    /**
291	     * Return this owner's telephone formatted for human display: the country code, a space, then
292	     * the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). The raw
293	     * {@link #getTelephone() telephone} remains in canonical E.164 form.
294	     */
295	    @Transient
296	    public String getTelephoneDisplay() {
297	        return TelephoneFormatter.format(this.telephone);
298	    }
299	
300	    /**
301	     * Return this owner's identity key: the derived value formed as
302	     * {@code normalizedTelephone + '|' + email + '|' + householdId} (an absent email or household id
303	     * contributes an empty segment). Members of the same household share a household id but, having
304	     * different telephones, still have distinct identity keys. The telephone and email are expected
305	     * to already be in their normalized storage form.
306	     */
307	    @Transient
308	    public String getIdentityKey() {
309	        return orEmpty(this.telephone) + "|" + orEmpty(this.email) + "|" + orEmpty(this.householdId);
310	    }
311	
312	    private static String orEmpty(String value) {
313	        return value == null ? "" : value;
314	    }
315	
316	    /**
317	     * Return this owner's locality: the REGION segment of the owner's
318	     * {@link #getCustomerCode() customer code}, which is the region the identity was minted for.
319	     * When no customer code has been assigned yet the region is resolved directly from the
320	     * {@link #getPostcode() postcode} and {@link #getCity() city} via {@link RegionResolver}.
321	     */
322	    @Transient
323	    public String getLocality() {
324	        if (this.customerCode != null && !this.customerCode.isBlank()) {
325	            return CustomerCodeGenerator.regionOf(this.customerCode);
326	        }
327	        return RegionResolver.regionFor(this.postcode, this.city);
328	    }
329	
330	    /**
331	     * Return this owner's timezone: the IANA name mapped from the owner's
332	     * {@link #getLocality() locality/region} via the fixed region-to-timezone table. Null when the
333	     * region has no known timezone.
334	     */
335	    @Transient
336	    public String getTimezone() {
337	        return RegionTimezones.timezoneOf(getLocality());
338	    }
339	
340	    /**
341	     * Return this owner's membership points: starting at 0, plus 2 when the owner has an email,
342	     * plus 1 when the owner is uniquely named (a {@link #getNamesakeCount() namesakeCount} of 0),
343	     * plus 2 for a household of three or more ({@link #getHouseholdSize() household size}), plus 3
344	     * for long tenure ({@link #getTenureFiscalYears() tenure} of more than one fiscal year).
345	     */
346	    @Transient
347	    public int getMembershipPoints() {
348	        boolean hasEmail = this.email != null && !this.email.isEmpty();
349	        boolean uniquelyNamed = Integer.valueOf(0).equals(this.namesakeCount);
350	        boolean largeHousehold = this.householdSize != null && this.householdSize >= 3;
351	        boolean longTenure = getTenureFiscalYears() > 1;
352	        return MembershipPoints.of(hasEmail, uniquelyNamed, largeHousehold, longTenure);
353	    }
354	
355	    /**
356	     * Return this owner's membership level: the band their {@link #getMembershipPoints() membership
357	     * points} fall into — 1 for 0-1 points, 2 for 2-3, 3 for 4-5, 4 for 6 or more.
358	     */
359	    @Transient
360	    public int getMembershipLevel() {
361	        return MembershipPoints.levelFor(getMembershipPoints());
362	    }
363	
364	    /**
365	     * Return this owner's fiscal year: the fiscal year of the business-day-adjusted
366	     * {@link #getRegistrationDate() registration date}, formatted {@code FY<YY>}. The fiscal year
367	     * starts on 1 July. Null when no registration date is known.
368	     */
369	    @Transient
370	    public String getFiscalYear() {
371	        return this.registrationDate == null ? null : FiscalYear.labelOf(this.registrationDate);
372	    }
373	
374	    /**
375	     * Return this owner's tenure in whole fiscal years: the number of fiscal years elapsed from the
376	     * {@link #getRegistrationDate() registration date} to today, i.e. the count of 1 July
377	     * fiscal-year boundaries crossed. A newly created owner registered in the current fiscal year
378	     * has zero tenure. Zero when no registration date is known.
379	     */
380	    @Transient
381	    public int getTenureFiscalYears() {
382	        if (this.registrationDate == null) {
383	            return 0;
384	        }
385	        return FiscalYear.elapsedBetween(this.registrationDate, LocalDate.now());
386	    }
387	
388	    /**
389	     * Return this owner's check digit: the single Luhn check digit computed over the
390	     * digits of the {@link #getCustomerCode() customer code}.
391	     */
392	    @Transient
393	    public int getCheckDigit() {
394	        return LuhnCheckDigit.of(this.customerCode);
395	    }
396	
397	    /**
398	     * Return this owner's preferred contact channel: {@code EMAIL} when an
399	     * {@link #getEmail() email} is present, otherwise {@code PHONE}.
400	     */
401	    @Transient
402	    public String getContactPreference() {
403	        boolean hasEmail = this.email != null && !this.email.isEmpty();
404	        return hasEmail ? "EMAIL" : "PHONE";
405	    }
406	
407	    /**
408	     * Return this owner's age band as of the {@link #getRegistrationDate() registration date},
409	     * derived from the {@link #getBirthDate() birth date}: {@code MINOR} under 18, {@code ADULT}
410	     * from 18 to 64, {@code SENIOR} at 65 or older. Null when no birth date is known.
411	     */
412	    @Transient
413	    public String getAgeBand() {
414	        AgeBand ageBand = AgeBand.asOf(this.birthDate, this.registrationDate);
415	        return ageBand == null ? null : ageBand.name();
416	    }
417	
418	    protected Set<Pet> getPetsInternal() {
419	        if (this.pets == null) {
420	            this.pets = new HashSet<>();
421	        }
422	        return this.pets;
423	    }
424	
425	    protected void setPetsInternal(Set<Pet> pets) {
426	        this.pets = pets;
427	    }
428	
429	    public List<Pet> getPets() {
430	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
431	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
432	        return Collections.unmodifiableList(sortedPets);
433	    }
434	
435	    public void setPets(List<Pet> pets) {
436	        this.pets = new HashSet<>(pets);
437	    }
438	
439	    public void addPet(Pet pet) {
440	        getPetsInternal().add(pet);
441	        pet.setOwner(this);
442	    }
443	
444	    /**
445	     * Return the Pet with the given name, or null if none found for this Owner.
446	     *
447	     * @param name to test
448	     * @return true if pet name is already in use
449	     */
450	    public Pet getPet(String name) {
451	        return getPet(name, false);
452	    }
453	
454	    /**
455	     * Return the Pet with the given name, or null if none found for this Owner.
456	     *
457	     * @param name to test
458	     * @return true if pet name is already in use
459	     */
460	    public Pet getPet(String name, boolean ignoreNew) {
461	        name = name.toLowerCase();
462	        for (Pet pet : getPetsInternal()) {
463	            if (!ignoreNew || !pet.isNew()) {
464	                String compName = pet.getName();
465	                compName = compName.toLowerCase();
466	                if (compName.equals(name)) {
467	                    return pet;
468	                }
469	            }
470	        }
471	        return null;
472	    }
473	
474	    public Pet getPet(Integer petId) {
475	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
476	    }
477	
478	    @Override
479	    public String toString() {
480	        return new ToStringCreator(this)
481	
482	            .append("id", this.getId())
483	            .append("new", this.isNew())
484	            .append("lastName", this.getLastName())
485	            .append("firstName", this.getFirstName())
486	            .append("address", this.address)
487	            .append("city", this.city)
488	            .append("telephone", this.telephone)
489	            .append("email", this.email)
490	            .toString();
491	    }
492	}
