16	package org.springframework.samples.petclinic.model;
17	
18	/**
19	 * The membership scoring rule: an owner earns points for the loyalty factors they satisfy, and the
20	 * accumulated points map onto a membership level. Points start at 0 and add up as follows: 2 for
21	 * having an email, 1 for being uniquely named, 2 for belonging to a household of three or more, and
22	 * 3 for tenure of more than one fiscal year. The level is a coarser banding of that score: 1 for 0-1 points,
23	 * 2 for 2-3, 3 for 4-5 and 4 for 6 or more.
24	 */
25	public final class MembershipPoints {
26	
27	    private static final int EMAIL_POINTS = 2;
28	    private static final int UNIQUE_NAME_POINTS = 1;
29	    private static final int LARGE_HOUSEHOLD_POINTS = 2;
30	    private static final int LONG_TENURE_POINTS = 3;
31	
32	    private MembershipPoints() {
33	    }
34	
35	    /**
36	     * The membership points earned for the given loyalty factors.
37	     *
38	     * @param hasEmail        whether the owner has an email
39	     * @param uniquelyNamed   whether the owner is uniquely named (no namesakes)
40	     * @param largeHousehold  whether the owner belongs to a household of three or more
41	     * @param longTenure      whether the owner's tenure exceeds one fiscal year
42	     * @return the total points, starting at 0
43	     */
44	    public static int of(boolean hasEmail, boolean uniquelyNamed, boolean largeHousehold, boolean longTenure) {
45	        int points = 0;
46	        if (hasEmail) {
47	            points += EMAIL_POINTS;
48	        }
49	        if (uniquelyNamed) {
50	            points += UNIQUE_NAME_POINTS;
51	        }
52	        if (largeHousehold) {
53	            points += LARGE_HOUSEHOLD_POINTS;
54	        }
55	        if (longTenure) {
56	            points += LONG_TENURE_POINTS;
57	        }
58	        return points;
59	    }
60	
61	    /**
62	     * The membership level the given points fall into: 1 for 0-1, 2 for 2-3, 3 for 4-5, 4 for 6+.
63	     *
64	     * @param points the membership points
65	     * @return the membership level, from 1 to 4
66	     */
67	    public static int levelFor(int points) {
68	        if (points <= 1) {
69	            return 1;
70	        }
71	        if (points <= 3) {
72	            return 2;
73	        }
74	        if (points <= 5) {
75	            return 3;
76	        }
77	        return 4;
78	    }
79	}
