18	
19	import org.springframework.samples.petclinic.service.ClinicService;
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Counts how many owners belong to a household, i.e. share a given {@link HouseholdKey household id},
24	 * including the owner being created. Owners with the same last name and postcode derive the same
25	 * household id (see {@link HouseholdKey}), so this size is the number of existing members plus the
26	 * new one.
27	 */
28	@Component
29	public class HouseholdSizeCounter {
30	
31	    private final ClinicService clinicService;
32	
33	    public HouseholdSizeCounter(ClinicService clinicService) {
34	        this.clinicService = clinicService;
35	    }
36	
37	    /**
38	     * Counts the members of the household identified by {@code householdId}, including the owner
39	     * being created. Returns 1 when no household id is known, since the owner then stands alone.
40	     *
41	     * @param householdId the household id of the owner being created
42	     * @return the number of existing owners sharing that household id, plus one for the new owner
43	     */
44	    public int count(String householdId) {
45	        if (householdId == null) {
46	            return 1;
47	        }
48	        long existing = this.clinicService.findAllOwners().stream()
49	            .filter(owner -> householdId.equals(owner.getHouseholdId()))
50	            .count();
51	        return (int) existing + 1;
52	    }
53	}
