74	@RestController
75	@CrossOrigin(exposedHeaders = "errors, content-type")
76	@RequestMapping("/api")
77	public class OwnerRestControllerV1 implements OwnersApi {
78	
79	    private final ClinicService clinicService;
80	
81	    private final OwnerMapper ownerMapper;
82	
83	    private final PetMapper petMapper;
84	
85	    private final VisitMapper visitMapper;
86	
87	    private final HouseholdDuplicateValidator householdDuplicateValidator;
88	
89	    private final PossibleDuplicateOwnerDetector possibleDuplicateOwnerDetector;
90	
91	    private final NamesakeCounter namesakeCounter;
