174	    /** Validate, derive and persist a brand-new owner from the submitted fields. */
175	    private Owner createOwner(OwnerFieldsDto ownerFieldsDto) {
176	        normalizeAddress(ownerFieldsDto);
177	        OwnerFieldsValidator.validateRequiredFields(ownerFieldsDto);
178	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
179	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
180	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
181	        DisposableEmailDomainValidator.validate(owner.getEmail());
182	        PostcodeValidator.validate(owner.getCity(), owner.getPostcode());
183	        RegistrationDateValidator.validateNotFuture(owner.getRegistrationDate());
184	        LocalDate effectiveDate = owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now();
185	        owner.setRegistrationDate(BusinessDayAdjuster.toBusinessDay(effectiveDate));
186	        this.dailyRegistrationCapacityValidator.validateHasCapacity(owner.getRegistrationDate());
187	        owner.setHouseholdId(HouseholdKey.idFor(owner.getLastName(), owner.getPostcode()));
188	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
189	            // An owner sharing a household (same last name and postcode) is otherwise a household
190	            // duplicate. A declared member bypasses this block, and is not a suspected duplicate.
191	            this.householdDuplicateValidator.rejectIfHouseholdExists(owner);
192	            this.possibleDuplicateOwnerDetector.findPossibleDuplicateOf(owner)
193	                .ifPresent(owner::setPossibleDuplicateOf);
194	        }
195	        this.cityOwnerCapacityValidator.validateHasCapacity(owner.getCity());
196	        owner.setNamesakeCount(this.namesakeCounter.count(owner.getFirstName(), owner.getLastName()));
197	        owner.setHouseholdSize(this.householdSizeCounter.count(owner.getHouseholdId()));
198	        String region = RegionResolver.regionFor(owner.getPostcode(), owner.getCity());
199	        String customerCode = CustomerCodeGenerator.generate(region, owner.getTelephone(), owner.getLastName());
200	        owner.setCustomerCode(this.customerCodeDeduplicator.deduplicate(customerCode));
201	        this.clinicService.saveOwner(owner);
